package io.scenariomesh.coordinator;import io.scenariomesh.core.*;import io.scenariomesh.core.Domain.*;import java.nio.file.*;import java.security.*;import java.util.*;
public final class FileBuildFingerprintStrategy implements Ports.BuildFingerprintStrategy{private final List<Path> roots;public FileBuildFingerprintStrategy(List<Path> roots){this.roots=List.copyOf(roots);}public BuildFingerprint calculate()throws Exception{var md=MessageDigest.getInstance("SHA-256");for(Path root:roots.stream().map(Path::toAbsolutePath).sorted().toList()){if(!Files.exists(root))continue;try(var s=Files.walk(root)){for(Path p:s.filter(Files::isRegularFile).sorted().toList()){md.update(root.relativize(p).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));md.update(Long.toString(Files.size(p)).getBytes());md.update(Long.toString(Files.getLastModifiedTime(p).toMillis()).getBytes());}}}return new BuildFingerprint(HexFormat.of().formatHex(md.digest()));}}
